function A({registerIndicator:y,sourceValues:N,nulls:b}){y({id:"oa-nma",name:"NMA - Natural Moving Average",category:"Trends IIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:40,min:1,max:5e3,step:1,tooltip:"Lookback window for the volatility analysis that sets the adaptive smoothing ratio."},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"nma",type:"line",title:"NMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(r,c){const u=Math.max(1,Math.floor(Number(c.period)||40)),m=N(r,c.source??"close"),d=r.length,h=new Array(d).fill(NaN),e=u+1,i=new Array(e).fill(0);let n=0,o=0;for(let t=0;t<d;t++){const l=Number.isFinite(m[t])?m[t]:0;i[n]=l>0?Math.log(l)*1e3:0;let f=0,s=0;const M=Math.min(t+1,u);for(let a=0;a<M;a++){const k=(n-a+e)%e,x=(n-a-1+e)%e,p=Math.abs(i[k]-i[x]);f+=p*(Math.sqrt(a+1)-Math.sqrt(a)),s+=p}n=(n+1)%e;const g=s!==0?f/s:0;t===0?o=l:o=o+g*(l-o),h[t]=Number.isFinite(o)?o:NaN}return{nma:b(h)}}})}export{A as default};
